DROP INDEX "notification_events_unseen_task_idx";--> statement-breakpoint
DROP INDEX "notification_events_unseen_ticket_idx";--> statement-breakpoint
CREATE INDEX "notification_events_unseen_task_idx" ON "notification_events" USING btree ("user_id",("payload" ->> 'taskId'),"created_at") WHERE ("notification_events"."kind" in ('task.assigned', 'task.moved', 'task.deadline', 'task.due_changed', 'task.overdue', 'chat.message', 'chat.mention', 'chat.thread_reply') and ("notification_events"."payload" ->> 'taskId') is not null);--> statement-breakpoint
CREATE INDEX "notification_events_unseen_ticket_idx" ON "notification_events" USING btree ("user_id",("payload" ->> 'ticketId'),"created_at") WHERE ("notification_events"."kind" in ('ticket.created', 'ticket.unassigned', 'ticket.message', 'ticket.status', 'ticket.updated', 'ticket.tasks', 'ticket.assigned', 'ticket.time_missing', 'ticket.resolved', 'chat.mention') and ("notification_events"."payload" ->> 'ticketId') is not null);